module.exports = {
  "partA": "    // ========================================================================\n    // 2. 3D WEBGL SCENE, 4-SYSTEM BIOMECHANICAL MOTIONS & HEAD-TO-TOE ANATOMY (v5.6)\n    // ========================================================================\n    const [THREE, { GLTFLoader }, { DRACOLoader }, { OrbitControls }] = await Promise.all([\n      import('https://esm.sh/three@0.166.0'),\n      import('https://esm.sh/three@0.166.0/examples/jsm/loaders/GLTFLoader.js'),\n      import('https://esm.sh/three@0.166.0/examples/jsm/loaders/DRACOLoader.js'),\n      import('https://esm.sh/three@0.166.0/examples/jsm/controls/OrbitControls.js')\n    ]);\n\n    const scene = new THREE.Scene();\n    const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 2000);\n    camera.setFocalLength(38);\n    camera.position.set(0.0, 2.28, 5.65);\n\n    const renderer = new THREE.WebGLRenderer({\n      canvas: canvas,\n      powerPreference: 'high-performance',\n      antialias: true,\n      alpha: true\n    });\n    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));\n    renderer.toneMapping = THREE.NoToneMapping;\n\n    const controls = new OrbitControls(camera, canvas);\n    controls.target.set(0.0, 2.26, 0.0);\n    controls.enableDamping = true;\n    controls.dampingFactor = 0.08;\n    controls.maxDistance = 7.5;\n    controls.minDistance = 0.65;\n    controls.maxPolarAngle = Math.PI * 0.84;\n    controls.minPolarAngle = Math.PI * 0.16;\n\n    const dracoLoader = new DRACOLoader();\n    dracoLoader.setDecoderPath('draco/');\n    const gltfLoader = new GLTFLoader();\n    gltfLoader.setDRACOLoader(dracoLoader);\n\n    // Shared reactive uniforms across all world-space shaders (synchronized 60fps motions + region focus)\n    const sharedMotionUniforms = {\n      uTime:        { value: 0.0 },\n      uMotionMode:  { value: 0.0 }, // 0=idle/clinic, 1=muscle, 2=nerve, 3=joint, 4=vessel\n      uMotionAmp:   { value: 1.0 },\n      uFocusActive: { value: 0.0 },\n      uFocusCenter: { value: new THREE.Vector3(0, 2.5, 0) },\n      uFocusRadius: { value: 0.38 }\n    };\n\n    // Synchronized Forward-Kinematics World-Space Body Motion (GLSL)\n    // Moves skin, muscles, skeleton, joints, brain, heart, nerves, and vessels in 100% lockstep\n    const GLSL_MOTION_CHUNK = [\n      'uniform float uTime;',\n      'uniform float uMotionMode;',\n      'uniform float uMotionAmp;',\n      'uniform float uFocusActive;',\n      'uniform vec3 uFocusCenter;',\n      'uniform float uFocusRadius;',\n      'vec2 rot2d(vec2 v, float a) {',\n      '  float c = cos(a); float s = sin(a);',\n      '  return vec2(v.x * c - v.y * s, v.x * s + v.y * c);',\n      '}',\n      'vec3 applySystemBodyMotion(vec3 wp) {',\n      '  if (uMotionMode < 0.5 || uMotionAmp < 0.001) return wp;',\n      '  vec3 p = wp;',\n      '  float absX = abs(p.x);',\n      '  float signX = p.x >= 0.0 ? 1.0 : -1.0;',\n      '  float innerArmX = mix(0.54, 0.41, clamp((p.y - 2.20) / 1.25, 0.0, 1.0));',\n      '  float armMask = smoothstep(innerArmX, innerArmX + 0.06, absX) * smoothstep(1.88, 2.00, p.y) * (1.0 - smoothstep(3.64, 3.80, p.y));',\n      '  float forearmMask = armMask * (1.0 - smoothstep(2.78, 2.94, p.y));',\n      '  float headNeckMask = smoothstep(3.64, 3.82, p.y) * (1.0 - smoothstep(0.24, 0.34, absX));',\n      '  float upperMask = smoothstep(2.38, 2.78, p.y);',\n      '  vec3 elbowPivot = vec3(signX * 0.59, 2.86, -0.09);',\n      '  vec3 shoulderPivot = vec3(signX * 0.43, 3.55, -0.10);',\n      '  vec3 neckPivot = vec3(0.0, 3.68, -0.06);',\n      '  vec3 waistPivot = vec3(0.0, 2.48, -0.04);',\n      '  if (uMotionMode < 1.5) {',\n      '    // 1. MUSCLE MODE: Athletic bicep/forearm curl + shoulder engagement + deep ribcage breathing + leg power flex',\n      '    float phase = 0.5 - 0.5 * cos(uTime * 2.2);',\n      '    float curlAng = phase * 0.44 * uMotionAmp * forearmMask;',\n      '    vec3 relE = p - elbowPivot;',\n      '    relE.yz = rot2d(relE.yz, -curlAng);',\n      '    p = elbowPivot + relE;',\n      '    float shAbduct = phase * 0.15 * uMotionAmp * armMask;',\n      '    vec3 relS = p - shoulderPivot;',\n      '    relS.xy = rot2d(relS.xy, signX * shAbduct);',\n      '    p = shoulderPivot + relS;',\n      '    float breath = sin(uTime * 2.2) * 0.5 + 0.5;',\n      '    float chestMask = smoothstep(2.75, 3.15, p.y) * (1.0 - smoothstep(3.62, 3.85, p.y)) * (1.0 - armMask);',\n      '    p.z += chestMask * breath * 0.018 * uMotionAmp;',\n      '    p.x += signX * chestMask * breath * 0.008 * uMotionAmp;',\n      '    float kneeSquat = phase * 0.028 * uMotionAmp;',\n      '    float kneeGlide = sin(clamp(p.y / 2.26, 0.0, 1.0) * 3.14159) * (1.0 - smoothstep(2.15, 2.38, p.y));',\n      '    p.z += kneeGlide * kneeSquat * 1.15;',\n      '    p.y -= smoothstep(0.18, 1.35, p.y) * kneeSquat * 0.65;',\n      '  } else if (uMotionMode < 2.5) {',\n      '    // 2. NERVE MODE: Cervical sensory scan + contralateral arm/hand neural reflex + proprioceptive balance',\n      '    float sidePhase = sin(uTime * 2.1 + (signX > 0.0 ? 0.0 : 3.14159));',\n      '    float reflexCurl = (0.5 + 0.5 * sidePhase) * 0.24 * uMotionAmp * forearmMask;',\n      '    vec3 relE = p - elbowPivot;',\n      '    relE.yz = rot2d(relE.yz, -reflexCurl);',\n      '    p = elbowPivot + relE;',\n      '    float shWave = (0.5 + 0.5 * sidePhase) * 0.09 * uMotionAmp * armMask;',\n      '    vec3 relS = p - shoulderPivot;',\n      '    relS.xy = rot2d(relS.xy, signX * shWave);',\n      '    p = shoulderPivot + relS;',\n      '    float neckYaw = sin(uTime * 1.35) * 0.16 * uMotionAmp * headNeckMask;',\n      '    float neckNod = sin(uTime * 2.7) * 0.05 * uMotionAmp * headNeckMask;',\n      '    vec3 relN = p - neckPivot;',\n      '    relN.xz = rot2d(relN.xz, neckYaw);',\n      '    relN.yz = rot2d(relN.yz, neckNod);',\n      '    p = neckPivot + relN;',\n      '    p.x += sin(uTime * 1.35) * 0.018 * uMotionAmp * upperMask;',\n      '  } else if (uMotionMode < 3.5) {',\n      '    // 3. JOINT MODE: Smooth multi-joint Range-of-Motion (ROM) articulation (shoulder, elbow, cervical, spine, knee)',\n      '    float rom = 0.5 - 0.5 * cos(uTime * 1.65);',\n      '    float elAng = (0.5 - 0.5 * cos(uTime * 1.65 + 0.55)) * 0.36 * uMotionAmp * forearmMask;',\n      '    vec3 relE = p - elbowPivot;',\n      '    relE.yz = rot2d(relE.yz, -elAng);',\n      '    p = elbowPivot + relE;',\n      '    float shAbduct = rom * 0.28 * uMotionAmp * armMask;',\n      '    float shSwing = sin(uTime * 1.65) * 0.11 * uMotionAmp * armMask;',\n      '    vec3 relS = p - shoulderPivot;',\n      '    relS.xy = rot2d(relS.xy, signX * shAbduct);',\n      '    relS.yz = rot2d(relS.yz, -shSwing);',\n      '    p = shoulderPivot + relS;',\n      '    float neckRot = sin(uTime * 1.65) * 0.18 * uMotionAmp * headNeckMask;',\n      '    vec3 relN = p - neckPivot;',\n      '    relN.xz = rot2d(relN.xz, neckRot);',\n      '    p = neckPivot + relN;',\n      '    float spineTwist = sin(uTime * 0.825) * 0.11 * uMotionAmp * upperMask;',\n      '    vec3 relW = p - waistPivot;',\n      '    relW.xz = rot2d(relW.xz, spineTwist);',\n      '    p = waistPivot + relW;',\n      '    float kneeRom = sin(clamp(p.y / 2.26, 0.0, 1.0) * 3.14159) * (1.0 - smoothstep(2.15, 2.38, p.y));',\n      '    p.z += kneeRom * rom * 0.036 * uMotionAmp;',\n      '  } else {',\n      '    // 4. VESSEL MODE: Cardiorespiratory chest expansion + Second-Heart calf venous pump heel-raise',\n      '    float pump = 0.5 - 0.5 * cos(uTime * 2.4);',\n      '    float shOpen = pump * 0.08 * uMotionAmp * armMask;',\n      '    vec3 relS = p - shoulderPivot;',\n      '    relS.xy = rot2d(relS.xy, signX * shOpen);',\n      '    p = shoulderPivot + relS;',\n      '    float calfPumpLift = pump * 0.026 * uMotionAmp * smoothstep(0.04, 0.24, p.y - max(0.0, p.z * 0.45));',\n      '    p.y += calfPumpLift;',\n      '    float chestBeat = sin(uTime * 3.8) * 0.5 + 0.5;',\n      '    float heartZone = exp(-length(p - vec3(0.03, 3.53, 0.02)) * 4.5);',\n      '    p.z += heartZone * chestBeat * 0.012 * uMotionAmp;',\n      '  }',\n      '  return p;',\n      '}',\n      'vec3 applyRegionFocusGlow(vec3 baseCol, vec3 origWorldPos) {',\n      '  if (uFocusActive < 0.5) return baseCol;',\n      '  float d = length(origWorldPos - uFocusCenter);',\n      '  float mask = 1.0 - smoothstep(uFocusRadius * 0.55, uFocusRadius * 1.25, d);',\n      '  float pulse = 0.55 + 0.45 * sin(uTime * 4.2);',\n      '  vec3 goldGlow = vec3(0.98, 0.86, 0.55);',\n      '  return mix(baseCol, goldGlow, mask * (0.34 + 0.22 * pulse));',\n      '}'\n    ].join('\\n');\n\n    // Matching JS motion evaluator so 3D hotspots stay glued to moving limbs/head\n    function rot2dJS(x, y, a) {\n      const c = Math.cos(a), s = Math.sin(a);\n      return [x * c - y * s, x * s + y * c];\n    }\n    function smoothstepJS(e0, e1, x) {\n      const t = Math.max(0, Math.min(1, (x - e0) / (e1 - e0)));\n      return t * t * (3 - 2 * t);\n    }\n    function evalSystemBodyMotionJS(wx, wy, wz) {\n      const mode = sharedMotionUniforms.uMotionMode.value;\n      const amp = sharedMotionUniforms.uMotionAmp.value;\n      const t = sharedMotionUniforms.uTime.value;\n      if (mode < 0.5 || amp < 0.001) return [wx, wy, wz];\n      let px = wx, py = wy, pz = wz;\n      const absX = Math.abs(px);\n      const signX = px >= 0 ? 1 : -1;\n      const innerArmX = 0.54 + (0.41 - 0.54) * Math.max(0, Math.min(1, (py - 2.20) / 1.25));\n      const armMask = smoothstepJS(innerArmX, innerArmX + 0.06, absX) * smoothstepJS(1.88, 2.00, py) * (1 - smoothstepJS(3.64, 3.80, py));\n      const forearmMask = armMask * (1 - smoothstepJS(2.78, 2.94, py));\n      const headNeckMask = smoothstepJS(3.64, 3.82, py) * (1 - smoothstepJS(0.24, 0.34, absX));\n      const upperMask = smoothstepJS(2.38, 2.78, py);\n      const ex = signX * 0.59, ey = 2.86, ez = -0.09;\n      const sx = signX * 0.43, sy = 3.55, sz = -0.10;\n      const nx = 0.0, ny = 3.68, nz = -0.06;\n      const wx0 = 0.0, wy0 = 2.48, wz0 = -0.04;\n\n      if (mode < 1.5) {\n        const phase = 0.5 - 0.5 * Math.cos(t * 2.2);\n        const curlAng = phase * 0.44 * amp * forearmMask;\n        let ry = py - ey, rz = pz - ez;\n        [ry, rz] = rot2dJS(ry, rz, -curlAng);\n        py = ey + ry; pz = ez + rz;\n        const shAbduct = phase * 0.15 * amp * armMask;\n        let rsx = px - sx, rsy = py - sy;\n        [rsx, rsy] = rot2dJS(rsx, rsy, signX * shAbduct);\n        px = sx + rsx; py = sy + rsy;\n        const kneeSquat = phase * 0.028 * amp;\n        const kneeGlide = Math.sin(Math.max(0, Math.min(1, py / 2.26)) * Math.PI) * (1 - smoothstepJS(2.15, 2.38, py));\n        pz += kneeGlide * kneeSquat * 1.15;\n        py -= smoothstepJS(0.18, 1.35, py) * kneeSquat * 0.65;\n      } else if (mode < 2.5) {\n        const sidePhase = Math.sin(t * 2.1 + (signX > 0 ? 0 : Math.PI));\n        const reflexCurl = (0.5 + 0.5 * sidePhase) * 0.24 * amp * forearmMask;\n        let ry = py - ey, rz = pz - ez;\n        [ry, rz] = rot2dJS(ry, rz, -reflexCurl);\n        py = ey + ry; pz = ez + rz;\n        const shWave = (0.5 + 0.5 * sidePhase) * 0.09 * amp * armMask;\n        let rsx = px - sx, rsy = py - sy;\n        [rsx, rsy] = rot2dJS(rsx, rsy, signX * shWave);\n        px = sx + rsx; py = sy + rsy;\n        const neckYaw = Math.sin(t * 1.35) * 0.16 * amp * headNeckMask;\n        const neckNod = Math.sin(t * 2.7) * 0.05 * amp * headNeckMask;\n        let rnx = px - nx, rny = py - ny, rnz = pz - nz;\n        [rnx, rnz] = rot2dJS(rnx, rnz, neckYaw);\n        [rny, rnz] = rot2dJS(rny, rnz, neckNod);\n        px = nx + rnx; py = ny + rny; pz = nz + rnz;\n        px += Math.sin(t * 1.35) * 0.018 * amp * upperMask;\n      } else if (mode < 3.5) {\n        const rom = 0.5 - 0.5 * Math.cos(t * 1.65);\n        const elAng = (0.5 - 0.5 * Math.cos(t * 1.65 + 0.55)) * 0.36 * amp * forearmMask;\n        let ry = py - ey, rz = pz - ez;\n        [ry, rz] = rot2dJS(ry, rz, -elAng);\n        py = ey + ry; pz = ez + rz;\n        const shAbduct = rom * 0.28 * amp * armMask;\n        const shSwing = Math.sin(t * 1.65) * 0.11 * amp * armMask;\n        let rsx = px - sx, rsy = py - sy, rsz = pz - sz;\n        [rsx, rsy] = rot2dJS(rsx, rsy, signX * shAbduct);\n        [rsy, rsz] = rot2dJS(rsy, rsz, -shSwing);\n        px = sx + rsx; py = sy + rsy; pz = sz + rsz;\n        const neckRot = Math.sin(t * 1.65) * 0.18 * amp * headNeckMask;\n        let rnx = px - nx, rnz = pz - nz;\n        [rnx, rnz] = rot2dJS(rnx, rnz, neckRot);\n        px = nx + rnx; pz = nz + rnz;\n        const spineTwist = Math.sin(t * 0.825) * 0.11 * amp * upperMask;\n        let rwx = px - wx0, rwz = pz - wz0;\n        [rwx, rwz] = rot2dJS(rwx, rwz, spineTwist);\n        px = wx0 + rwx; pz = wz0 + rwz;\n        const kneeRom = Math.sin(Math.max(0, Math.min(1, py / 2.26)) * Math.PI) * (1 - smoothstepJS(2.15, 2.38, py));\n        pz += kneeRom * rom * 0.036 * amp;\n      } else {\n        const pump = 0.5 - 0.5 * Math.cos(t * 2.4);\n        const shOpen = pump * 0.08 * amp * armMask;\n        let rsx = px - sx, rsy = py - sy;\n        [rsx, rsy] = rot2dJS(rsx, rsy, signX * shOpen);\n        px = sx + rsx; py = sy + rsy;\n        const calfPumpLift = pump * 0.026 * amp * smoothstepJS(0.04, 0.24, py - Math.max(0, pz * 0.45));\n        py += calfPumpLift;\n      }\n      return [px, py, pz];\n    }\n\n    // 2.1 Dual Porcelain Mannequin + Écorché Striated Muscle Body Shader (for 193k-vertex MBLab Body)\n    function createStylizedPorcelainBodyMaterial() {\n      return new THREE.ShaderMaterial({\n        uniforms: Object.assign({\n          uHighlightCol: { value: new THREE.Color('#FAF6EC') },\n          uMidCol:       { value: new THREE.Color('#EFE6D5') },\n          uRimCol:       { value: new THREE.Color('#D2C2A8') },\n          uOutlineCol:   { value: new THREE.Color('#6E5844') },\n          uCenterAlpha:  { value: 0.88 },\n          uMuscleMode:   { value: 0.0 }\n        }, sharedMotionUniforms),\n        vertexShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform float uMuscleMode;',\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vec4 origWorld = modelMatrix * vec4(position, 1.0);',\n          '  vOrigWorldPos = origWorld.xyz;',\n          '  vec3 localMoved = position;',\n          '  if (uMuscleMode > 0.5) {',\n          '    float flexWave = 0.5 - 0.5 * cos(uTime * 2.2);',\n          '    float armBicep = smoothstep(0.48, 0.56, abs(origWorld.x)) * smoothstep(2.88, 3.00, origWorld.y) * (1.0 - smoothstep(3.32, 3.45, origWorld.y));',\n          '    float legBelly = (1.0 - smoothstep(1.90, 2.08, origWorld.y)) * smoothstep(0.40, 0.65, origWorld.y);',\n          '    localMoved += normal * (flexWave * 0.0032 * clamp(armBicep + legBelly, 0.0, 1.0) * uMotionAmp);',\n          '  }',\n          '  vec4 worldPos = modelMatrix * vec4(localMoved, 1.0);',\n          '  worldPos.xyz = applySystemBodyMotion(worldPos.xyz);',\n          '  vec4 mvPos = viewMatrix * worldPos;',\n          '  vViewDir = normalize(-mvPos.xyz);',\n          '  vNormal = normalize(normalMatrix * normal);',\n          '  gl_Position = projectionMatrix * mvPos;',\n          '}'\n        ].join('\\n'),\n        fragmentShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform vec3 uHighlightCol;',\n          'uniform vec3 uMidCol;',\n          'uniform vec3 uRimCol;',\n          'uniform vec3 uOutlineCol;',\n          'uniform float uCenterAlpha;',\n          'uniform float uMuscleMode;',\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vec3 N = normalize(vNormal);',\n          '  vec3 V = normalize(vViewDir);',\n          '  vec3 L = normalize(vec3(0.42, 0.78, 0.68));',\n          '  float faceMask = smoothstep(3.96, 4.10, vOrigWorldPos.y) * (1.0 - smoothstep(4.40, 4.54, vOrigWorldPos.y));',\n          '  vec3 smoothFaceN = normalize(vec3(N.x * 0.92, N.y * 0.35, max(abs(N.z), 0.66)));',\n          '  vec3 effN = normalize(mix(N, smoothFaceN, faceMask * (1.0 - uMuscleMode * 0.65) * 0.84));',\n          '  float NdotL = dot(effN, L) * 0.5 + 0.5;',\n          '  float NdotV = clamp(abs(dot(effN, V)), 0.0, 1.0);',\n          '  float rim = 1.0 - NdotV;',\n          '  if (uMuscleMode > 0.5) {',\n          '    // Anatomical Écorché Striated Muscle + Silvery-Ivory Tendon/Aponeurosis Shader',\n          '    float absX = abs(vOrigWorldPos.x);',\n          '    float pecAngle = vOrigWorldPos.x * 46.0 + (vOrigWorldPos.y - 3.42) * 28.0;',\n          '    float vertAngle = vOrigWorldPos.x * 78.0 + vOrigWorldPos.z * 52.0;',\n          '    float chestZone = smoothstep(3.12, 3.28, vOrigWorldPos.y) * (1.0 - smoothstep(3.58, 3.72, vOrigWorldPos.y)) * (1.0 - smoothstep(0.28, 0.42, absX));',\n          '    float striaCoord = mix(vertAngle, pecAngle, chestZone);',\n          '    float stria = 0.5 + 0.5 * sin(striaCoord);',\n          '    float fineStria = 0.5 + 0.5 * sin(striaCoord * 2.6 + vOrigWorldPos.y * 18.0);',\n          '    float fiberVal = mix(stria, fineStria, 0.35);',\n          '    // Tendon / Aponeurosis anatomical masks (galea, linea alba, retinacula, IT band, patellar, Achilles)',\n          '    float galea = smoothstep(4.41, 4.50, vOrigWorldPos.y);',\n          '    float lineaAlba = (1.0 - smoothstep(0.008, 0.024, absX)) * smoothstep(2.45, 2.60, vOrigWorldPos.y) * (1.0 - smoothstep(3.35, 3.50, vOrigWorldPos.y)) * smoothstep(0.0, 0.06, vOrigWorldPos.z);',\n          '    float absIntersections = (1.0 - smoothstep(0.02, 0.11, absX)) * smoothstep(0.02, 0.08, vOrigWorldPos.z) * smoothstep(2.68, 2.75, vOrigWorldPos.y) * (1.0 - smoothstep(3.22, 3.28, vOrigWorldPos.y)) * pow(max(0.0, sin((vOrigWorldPos.y - 2.72) * 19.5)), 12.0);',\n          '    float lumbarFascia = (1.0 - smoothstep(0.03, 0.11, absX)) * (1.0 - smoothstep(-0.04, 0.01, vOrigWorldPos.z)) * smoothstep(2.32, 2.50, vOrigWorldPos.y) * (1.0 - smoothstep(2.95, 3.12, vOrigWorldPos.y));',\n          '    float wristHandTendon = smoothstep(0.60, 0.68, absX) * (1.0 - smoothstep(2.26, 2.40, vOrigWorldPos.y));',\n          '    float kneeTendon = smoothstep(1.04, 1.13, vOrigWorldPos.y) * (1.0 - smoothstep(1.26, 1.35, vOrigWorldPos.y)) * smoothstep(-0.16, -0.09, vOrigWorldPos.z);',\n          '    float ankleFootTendon = 1.0 - smoothstep(0.14, 0.32, vOrigWorldPos.y);',\n          '    float tendonMask = clamp(galea * 0.85 + lineaAlba * 0.90 + absIntersections * 0.65 + lumbarFascia * 0.78 + wristHandTendon * 0.72 + kneeTendon * 0.78 + ankleFootTendon * 0.76, 0.0, 0.92);',\n          '    vec3 musHigh = vec3(0.89, 0.43, 0.39);',\n          '    vec3 musMid  = vec3(0.71, 0.24, 0.21);',\n          '    vec3 musDeep = vec3(0.45, 0.12, 0.11);',\n          '    vec3 mCol = mix(musDeep, musMid, smoothstep(0.28, 0.45, NdotL));',\n          '    mCol = mix(mCol, musHigh, smoothstep(0.62, 0.76, NdotL));',\n          '    mCol = mix(mCol * 0.84, mCol * 1.10, fiberVal);',\n          '    vec3 tendonCol = mix(vec3(0.82, 0.76, 0.68), vec3(0.96, 0.93, 0.88), smoothstep(0.38, 0.68, NdotL));',\n          '    vec3 finalMus = mix(mCol, tendonCol, tendonMask);',\n          '    float flexGlow = 0.5 - 0.5 * cos(uTime * 2.2);',\n          '    finalMus += vec3(0.10, 0.03, 0.02) * flexGlow * (1.0 - tendonMask);',\n          '    finalMus = mix(finalMus, vec3(0.32, 0.10, 0.09), smoothstep(0.76, 0.90, rim) * 0.65);',\n          '    finalMus = applyRegionFocusGlow(finalMus, vOrigWorldPos);',\n          '    gl_FragColor = vec4(finalMus, 0.96);',\n          '    return;',\n          '  }',\n          '  float toonBand = smoothstep(0.38, 0.46, NdotL);',\n          '  vec3 baseCol = mix(uMidCol, uHighlightCol, toonBand);',\n          '  float rimBand = smoothstep(0.54, 0.74, rim);',\n          '  float inkOutline = smoothstep(0.80, 0.90, rim);',\n          '  vec3 col = mix(baseCol, uRimCol, rimBand * 0.60);',\n          '  col = mix(col, uOutlineCol, inkOutline * 0.50);',\n          '  float alpha = mix(uCenterAlpha, 0.92, pow(rim, 1.50));',\n          '  gl_FragColor = vec4(col, alpha);',\n          '}'\n        ].join('\\n'),\n        transparent: true,\n        depthWrite: true,\n        side: THREE.FrontSide\n      });\n    }\n\n    const maleSkinMat = createStylizedPorcelainBodyMaterial();\n    const femaleSkinMat = createStylizedPorcelainBodyMaterial();\n    let maleBodyObj = null;\n    let femaleBodyObj = null;\n    let currentGender = 'male';\n\n    gltfLoader.load('models/skinMB2.glb', (gltf) => {\n      maleBodyObj = gltf.scene;\n      maleBodyObj.traverse(c => {\n        if (c.isMesh) {\n          c.material = maleSkinMat;\n          c.renderOrder = 10;\n        }\n      });\n      scene.add(maleBodyObj);\n      if (loaderOverlay) loaderOverlay.classList.add('hidden');\n    });\n\n    gltfLoader.load('models/skinF2.glb', (gltf) => {\n      femaleBodyObj = gltf.scene;\n      femaleBodyObj.visible = false;\n      femaleBodyObj.traverse(c => {\n        if (c.isMesh) {\n          c.material = femaleSkinMat;\n          c.renderOrder = 10;\n        }\n      });\n      scene.add(femaleBodyObj);\n    });\n\n    // 2.2 Smooth Lifelike Cel-Shaded Clay Shader for Organs, Bones & Joints (Synchronized with FK Motion + Focus Glow)\n    function createToonClayMaterial(hiHex, midHex, shdHex, outHex, initialOpacity = 0.96, smoothFactor = 0.72, extraPulseMode = 0.0) {\n      return new THREE.ShaderMaterial({\n        uniforms: Object.assign({\n          uHigh:       { value: new THREE.Color(hiHex) },\n          uMid:        { value: new THREE.Color(midHex) },\n          uShadow:     { value: new THREE.Color(shdHex) },\n          uOutline:    { value: new THREE.Color(outHex) },\n          uOpacity:    { value: initialOpacity },\n          uCenter:     { value: new THREE.Vector3(0, 0, 0) },\n          uSmooth:     { value: smoothFactor },\n          uExtraPulse: { value: extraPulseMode } // 1.0 = cardiac lub-dub, 2.0 = synovial joint glow\n        }, sharedMotionUniforms),\n        vertexShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform vec3 uCenter;',\n          'uniform float uExtraPulse;',\n          'varying vec3 vNormal;',\n          'varying vec3 vRadial;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vec3 localPos = position;',\n          '  if (uExtraPulse > 0.5 && uExtraPulse < 1.5 && uMotionMode > 3.5) {',\n          '    float lub = pow(max(0.0, sin(uTime * 3.8)), 6.0);',\n          '    float dub = 0.55 * pow(max(0.0, sin(uTime * 3.8 - 0.65)), 8.0);',\n          '    float beat = 1.0 + (lub + dub) * 0.085;',\n          '    localPos = uCenter + (position - uCenter) * beat;',\n          '  }',\n          '  vec4 origWorld = modelMatrix * vec4(localPos, 1.0);',\n          '  vOrigWorldPos = origWorld.xyz;',\n          '  vec4 worldPos = vec4(applySystemBodyMotion(origWorld.xyz), 1.0);',\n          '  vec4 mvPos = viewMatrix * worldPos;',\n          '  vViewDir = normalize(-mvPos.xyz);',\n          '  vNormal = normalize(normalMatrix * normal);',\n          '  vec3 radLocal = position - uCenter;',\n          '  float rLen = length(radLocal);',\n          '  vRadial = rLen > 0.0001 ? normalize(normalMatrix * (radLocal / rLen)) : vNormal;',\n          '  gl_Position = projectionMatrix * mvPos;',\n          '}'\n        ].join('\\n'),\n        fragmentShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform vec3 uHigh;',\n          'uniform vec3 uMid;',\n          'uniform vec3 uShadow;',\n          'uniform vec3 uOutline;',\n          'uniform float uOpacity;',\n          'uniform float uSmooth;',\n          'uniform float uExtraPulse;',\n          'varying vec3 vNormal;',\n          'varying vec3 vRadial;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vec3 N = normalize(mix(normalize(vNormal), normalize(vRadial), uSmooth));',\n          '  vec3 V = normalize(vViewDir);',\n          '  vec3 L = normalize(vec3(0.38, 0.72, 0.68));',\n          '  float nl = dot(N, L) * 0.5 + 0.5;',\n          '  float nv = clamp(abs(dot(N, V)), 0.0, 1.0);',\n          '  float band1 = smoothstep(0.35, 0.42, nl);',\n          '  float band2 = smoothstep(0.65, 0.72, nl);',\n          '  vec3 col = mix(uShadow, uMid, band1);',\n          '  col = mix(col, uHigh, band2);',\n          '  vec3 H = normalize(L + V);',\n          '  float spec = smoothstep(0.90, 0.95, max(0.0, dot(N, H)));',\n          '  col = mix(col, vec3(0.99, 0.98, 0.95), spec * 0.45);',\n          '  if (uExtraPulse > 1.5) {',\n          '    float jPulse = 0.5 + 0.5 * sin(uTime * 3.3 - vOrigWorldPos.y * 2.2);',\n          '    col = mix(col, vec3(0.96, 0.86, 0.58), jPulse * 0.24);',\n          '  }',\n          '  float ink = smoothstep(0.75, 0.87, 1.0 - nv);',\n          '  col = mix(col, uOutline, ink * 0.70);',\n          '  col = applyRegionFocusGlow(col, vOrigWorldPos);',\n          '  gl_FragColor = vec4(col, uOpacity);',\n          '}'\n        ].join('\\n'),\n        transparent: true,\n        depthWrite: true\n      });\n    }\n\n    // 2.3 Full Head-to-Toe Skeleton (Skeleton.glb — All 9 Anatomical Bone Groups) + Joints.glb Articular Cartilage\n    const boneIllustrationMap = {};\n    gltfLoader.load('models/Skeleton.glb', (gltf) => {\n      gltf.scene.traverse(c => {\n        if (c.isMesh) {\n          const gName = c.name || c.parent?.name || '';\n          c.geometry.computeBoundingBox();\n          const center = new THREE.Vector3();\n          c.geometry.boundingBox.getCenter(center);\n          const isGP = gName.includes('KneeGrowthPlate');\n          const mat = isGP\n            ? createToonClayMaterial('#72D1A0', '#3C9468', '#226141', '#163D29', 0.98, 0.25, 2.0)\n            : createToonClayMaterial('#FAF3E4', '#E2D2B8', '#BA9F7C', '#4D3722', 0.94, 0.22, 0.0);\n          mat.uniforms.uCenter.value.copy(center);\n          c.material = mat;\n          c.visible = false;\n          c.renderOrder = isGP ? 6 : 3;\n          boneIllustrationMap[gName] = { mesh: c, mat: mat };\n        }\n      });\n      scene.add(gltf.scene);\n      updateAnatomyHighlight();\n    });\n\n    // 2.3a Full-Body Articular Capsules, Menisci & Intervertebral Discs (Joints.glb: TMJ to Finger & Toe Joints)\n    let jointsGlbGroup = null;\n    const jointsGlbMats = [];\n    gltfLoader.load('models/Joints.glb', (gltf) => {\n      jointsGlbGroup = gltf.scene;\n      jointsGlbGroup.visible = false;\n      jointsGlbGroup.traverse(c => {\n        if (c.isMesh) {\n          c.geometry.computeBoundingBox();\n          const center = new THREE.Vector3();\n          c.geometry.boundingBox.getCenter(center);\n          const mName = c.name || '';\n          const jMat = mName.includes('SpinalDiscs')\n            ? createToonClayMaterial('#9BE8FA', '#4DB0CC', '#27728A', '#144152', 0.97, 0.28, 2.0)\n            : createToonClayMaterial('#F5DC9B', '#CFA44E', '#916B22', '#4A340B', 0.97, 0.26, 2.0);\n          jMat.uniforms.uCenter.value.copy(center);\n          c.material = jMat;\n          c.renderOrder = 6;\n          jointsGlbMats.push(jMat);\n        }\n      });\n      scene.add(jointsGlbGroup);\n      updateAnatomyHighlight();\n    });\n\n    // 2.3b Clean Custom 3D Intervertebral Discs for Clinic Cervical/Lumbar Views\n    function createSpinalDiscs3DGroup() {\n      const group = new THREE.Group();\n      const discMat = createToonClayMaterial('#9BE8FA', '#52B2CC', '#2B758C', '#164454', 0.96, 0.30, 0.0);\n      const highlightDiscMat = createToonClayMaterial('#B8F2FF', '#64C5E0', '#3489A3', '#184A59', 0.98, 0.25, 0.0);\n\n      const lumbarDiscSpecs = [\n        { y: 2.935, z: -0.042, rx: 0.044, rz: 0.034, h: 0.022, tilt:  0.03, highlight: false },\n        { y: 2.845, z: -0.038, rx: 0.047, rz: 0.036, h: 0.024, tilt:  0.05, highlight: false },\n        { y: 2.752, z: -0.035, rx: 0.050, rz: 0.038, h: 0.025, tilt:  0.08, highlight: true  },\n        { y: 2.660, z: -0.038, rx: 0.052, rz: 0.039, h: 0.026, tilt:  0.14, highlight: true  },\n        { y: 2.572, z: -0.046, rx: 0.050, rz: 0.037, h: 0.024, tilt:  0.22, highlight: true  }\n      ];\n      lumbarDiscSpecs.forEach(d => {\n        const geo = new THREE.CylinderGeometry(d.rx, d.rx, d.h, 32, 1);\n        geo.scale(1.0, 1.0, d.rz / d.rx);\n        const mesh = new THREE.Mesh(geo, d.highlight ? highlightDiscMat : discMat);\n        mesh.position.set(0, d.y, d.z);\n        mesh.rotation.x = d.tilt;\n        mesh.renderOrder = 6;\n        group.add(mesh);\n      });\n\n      const cervicalDiscSpecs = [\n        { y: 3.865, z: -0.072, r: 0.026, h: 0.015 },\n        { y: 3.795, z: -0.075, r: 0.028, h: 0.016 },\n        { y: 3.725, z: -0.078, r: 0.030, h: 0.016 },\n        { y: 3.655, z: -0.082, r: 0.032, h: 0.017 }\n      ];\n      cervicalDiscSpecs.forEach(d => {\n        const geo = new THREE.CylinderGeometry(d.r, d.r, d.h, 28, 1);\n        geo.scale(1.0, 1.0, 0.78);\n        const mesh = new THREE.Mesh(geo, discMat);\n        mesh.position.set(0, d.y, d.z);\n        mesh.rotation.x = -0.06;\n        mesh.renderOrder = 6;\n        group.add(mesh);\n      });\n\n      const pubGeo = new THREE.BoxGeometry(0.018, 0.055, 0.028);\n      const pubMesh = new THREE.Mesh(pubGeo, discMat);\n      pubMesh.position.set(0, 2.20, 0.068);\n      pubMesh.renderOrder = 6;\n      group.add(pubMesh);\n\n      group.visible = false;\n      scene.add(group);\n      return { group, mats: [discMat, highlightDiscMat] };\n    }\n    const spinalDiscs3D = createSpinalDiscs3DGroup();\n\n    // 2.4 Lifelike Natural Colored Internal Organs\n    const loadedOrgans = {};\n    const STYLIZED_ORGANS = [\n      {\n        key: 'brain', file: 'models/brain.glb', parts: ['gongjindan', 'cervical', 'syncope'],\n        smooth: 0.80, pulse: 0.0,\n        activeCols: ['#F2CEC4', '#DBA496', '#AD7366', '#5E3830']\n      },\n      {\n        key: 'heart', file: 'models/heart.glb', parts: ['gongjindan', 'syncope'],\n        smooth: 0.65, pulse: 1.0,\n        activeCols: ['#E36B62', '#BE433B', '#8C2923', '#4A120F']\n      },\n      {\n        key: 'liver', file: 'models/liver.glb', parts: ['gut', 'digest'],\n        smooth: 0.72, pulse: 0.0,\n        activeCols: ['#BF6556', '#994638', '#6E2C21', '#3D150E']\n      },\n      {\n        key: 'stomach', file: 'models/stomach.glb', parts: ['digest', 'gut'],\n        smooth: 0.68, pulse: 0.0,\n        activeCols: ['#F0A892', '#D47E66', '#A35540', '#54271B']\n      },\n      {\n        key: 'intestine', file: 'models/intestine.glb', parts: ['digest', 'gut'],\n        smooth: 0.80, pulse: 0.0,\n        activeCols: ['#EBB9AA', '#CC9180', '#9C6454', '#523127']\n      },\n      {\n        key: 'kidneys', file: 'models/kidneys2.glb', parts: ['lumbar', 'prostate'],\n        smooth: 0.66, pulse: 0.0,\n        activeCols: ['#C96D63', '#A14A41', '#732D26', '#3D1410']\n      },\n      {\n        key: 'thyroid', file: 'models/thyroid.glb', parts: ['cervical'],\n        smooth: 0.62, pulse: 0.0,\n        activeCols: ['#E8988E', '#C46C62', '#8F443B', '#4A1F1A']\n      }\n    ];\n\n    STYLIZED_ORGANS.forEach(cfg => {\n      gltfLoader.load(cfg.file, (gltf) => {\n        const mat = createToonClayMaterial(...cfg.activeCols, 0.96, cfg.smooth, cfg.pulse);\n        const rootMesh = gltf.scene.children[0] || gltf.scene;\n        if (cfg.key === 'brain' && rootMesh) {\n          rootMesh.scale.multiplyScalar(0.86);\n          rootMesh.position.y -= 0.042;\n        }\n        gltf.scene.traverse(c => {\n          if (c.isMesh) {\n            c.geometry.computeBoundingBox();\n            const center = new THREE.Vector3();\n            c.geometry.boundingBox.getCenter(center);\n            mat.uniforms.uCenter.value.copy(center);\n            c.material = mat;\n            c.renderOrder = 4;\n          }\n        });\n        gltf.scene.visible = false;\n        scene.add(gltf.scene);\n        loadedOrgans[cfg.key] = {\n          scene: gltf.scene,\n          mesh: rootMesh,\n          mat: mat,\n          cfg: cfg\n        };\n        updateAnatomyHighlight();\n      });\n    });\n\n    // 2.5 Custom 3D Uterus + Fallopian Tubes + Ovaries Graphic\n    function createUterus3DGroup() {\n      const group = new THREE.Group();\n      group.position.set(0.0, 2.42, 0.02);\n\n      const uterusMat = createToonClayMaterial('#EB8A90', '#C95A62', '#91353C', '#4F181D', 0.98, 0.35);\n      const ovaryMat  = createToonClayMaterial('#FAF0E4', '#E2CBB5', '#B89E84', '#5C4632', 0.98, 0.35);\n      const glowMat   = createToonClayMaterial('#FFD4C4', '#F59E8E', '#C96B5B', '#7A3328', 0.98, 0.25);\n\n      const lathePts = [\n        new THREE.Vector2(0.000, -0.085),\n        new THREE.Vector2(0.016, -0.080),\n        new THREE.Vector2(0.018, -0.045),\n        new THREE.Vector2(0.026, -0.010),\n        new THREE.Vector2(0.044,  0.030),\n        new THREE.Vector2(0.052,  0.058),\n        new THREE.Vector2(0.038,  0.076),\n        new THREE.Vector2(0.000,  0.082)\n      ];\n      const bodyGeo = new THREE.LatheGeometry(lathePts, 36);\n      bodyGeo.scale(1.0, 1.0, 0.62);\n      const bodyMesh = new THREE.Mesh(bodyGeo, uterusMat);\n      bodyMesh.renderOrder = 6;\n      group.add(bodyMesh);\n\n      const coreGeo = new THREE.SphereGeometry(0.022, 24, 24);\n      coreGeo.scale(1.0, 1.25, 0.72);\n      const coreMesh = new THREE.Mesh(coreGeo, glowMat);\n      coreMesh.position.set(0, 0.032, 0.018);\n      coreMesh.renderOrder = 7;\n      group.add(coreMesh);\n\n      [-1, 1].forEach(dir => {\n        const tubeCurve = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.040,  0.058,  0.000),\n          new THREE.Vector3(dir * 0.082,  0.068, -0.004),\n          new THREE.Vector3(dir * 0.125,  0.052, -0.008),\n          new THREE.Vector3(dir * 0.142,  0.022, -0.006),\n          new THREE.Vector3(dir * 0.126,  0.004, -0.004)\n        ]);\n        const tubeGeo = new THREE.TubeGeometry(tubeCurve, 32, 0.0095, 16, false);\n        const tubeMesh = new THREE.Mesh(tubeGeo, uterusMat);\n        tubeMesh.renderOrder = 6;\n        group.add(tubeMesh);\n\n        const ovGeo = new THREE.SphereGeometry(0.022, 24, 24);\n        ovGeo.scale(1.25, 0.85, 0.70);\n        const ovMesh = new THREE.Mesh(ovGeo, ovaryMat);\n        ovMesh.position.set(dir * 0.105, 0.008, -0.004);\n        ovMesh.rotation.z = dir * 0.25;\n        ovMesh.renderOrder = 6;\n        group.add(ovMesh);\n\n        const ligCurve = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.036, 0.032, 0.000),\n          new THREE.Vector3(dir * 0.086, 0.012, -0.004)\n        ]);\n        const ligGeo = new THREE.TubeGeometry(ligCurve, 12, 0.0045, 10, false);\n        const ligMesh = new THREE.Mesh(ligGeo, ovaryMat);\n        ligMesh.renderOrder = 6;\n        group.add(ligMesh);\n      });\n\n      group.visible = false;\n      scene.add(group);\n      return { group, mats: [uterusMat, ovaryMat, glowMat] };\n    }\n    const uterus3D = createUterus3DGroup();\n\n    // 2.6 Custom 3D Prostate + Urinary Bladder + Ureters Graphic\n    function createProstate3DGroup() {\n      const group = new THREE.Group();\n      group.position.set(0.0, 2.26, 0.03);\n\n      const bladderMat  = createToonClayMaterial('#F0B594', '#D18B66', '#9E5D3C', '#522B18', 0.98, 0.35);\n      const prostateMat = createToonClayMaterial('#E0756C', '#B84B43', '#822923', '#47120E', 0.98, 0.35);\n      const tractMat    = createToonClayMaterial('#FAE8C8', '#DEC296', '#B09264', '#59462A', 0.98, 0.30);\n\n      const blGeo = new THREE.SphereGeometry(0.058, 32, 32);\n      blGeo.scale(1.12, 0.92, 0.85);\n      const blMesh = new THREE.Mesh(blGeo, bladderMat);\n      blMesh.position.set(0, 0.062, 0.004);\n      blMesh.renderOrder = 6;\n      group.add(blMesh);\n\n      [-1, 1].forEach(dir => {\n        const lobeGeo = new THREE.SphereGeometry(0.028, 28, 28);\n        lobeGeo.scale(0.95, 1.05, 0.85);\n        const lobeMesh = new THREE.Mesh(lobeGeo, prostateMat);\n        lobeMesh.position.set(dir * 0.014, -0.004, 0.002);\n        lobeMesh.renderOrder = 7;\n        group.add(lobeMesh);\n      });\n\n      const urethraCurve = new THREE.CatmullRomCurve3([\n        new THREE.Vector3(0,  0.045, 0.018),\n        new THREE.Vector3(0, -0.005, 0.018),\n        new THREE.Vector3(0, -0.058, 0.016)\n      ]);\n      const urethraMesh = new THREE.Mesh(new THREE.TubeGeometry(urethraCurve, 20, 0.0055, 12, false), tractMat);\n      urethraMesh.renderOrder = 8;\n      group.add(urethraMesh);\n\n      [-1, 1].forEach(dir => {\n        const ureterCurve = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.046, 0.088, -0.010),\n          new THREE.Vector3(dir * 0.062, 0.165, -0.020),\n          new THREE.Vector3(dir * 0.072, 0.250, -0.030)\n        ]);\n        const ureterMesh = new THREE.Mesh(new THREE.TubeGeometry(ureterCurve, 20, 0.0048, 10, false), tractMat);\n        ureterMesh.renderOrder = 6;\n        group.add(ureterMesh);\n      });\n\n      group.visible = false;\n      scene.add(group);\n      return { group, mats: [bladderMat, prostateMat, tractMat] };\n    }\n    const prostate3D = createProstate3DGroup();\n\n    // 2.7 Whole-Body Blood Vessels (Vascular.glb) with Arterial Outflow / Venous Return Hemodynamic Pulse Shader\n    function createVascularMaterial(highHex, midHex, shadowHex, outlineHex, opacity, flowDir) {\n      return new THREE.ShaderMaterial({\n        uniforms: Object.assign({\n          uHigh:       { value: new THREE.Color(highHex) },\n          uMid:        { value: new THREE.Color(midHex) },\n          uShadow:     { value: new THREE.Color(shadowHex) },\n          uOutline:    { value: new THREE.Color(outlineHex) },\n          uOpacity:    { value: opacity },\n          uClipPelvis: { value: 1.0 },\n          uFlowDir:    { value: flowDir } // -1.0 = arterial (from heart outward), +1.0 = venous (to heart)\n        }, sharedMotionUniforms),\n        vertexShader: [\n          GLSL_MOTION_CHUNK,\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vLocalPos;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vLocalPos = position;',\n          '  vec4 origWorld = modelMatrix * vec4(position, 1.0);',\n          '  vOrigWorldPos = origWorld.xyz;',\n          '  vec4 worldPos = vec4(applySystemBodyMotion(origWorld.xyz), 1.0);',\n          '  vec4 mvPos = viewMatrix * worldPos;',\n          '  vViewDir = normalize(-mvPos.xyz);',\n          '  vNormal = normalize(normalMatrix * normal);',\n          '  gl_Position = projectionMatrix * mvPos;',\n          '}'\n        ].join('\\n'),\n        fragmentShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform vec3 uHigh;',\n          'uniform vec3 uMid;',\n          'uniform vec3 uShadow;',\n          'uniform vec3 uOutline;',\n          'uniform float uOpacity;',\n          'uniform float uClipPelvis;',\n          'uniform float uFlowDir;',\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vLocalPos;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  if (uClipPelvis > 0.5 && vLocalPos.y > 1.92 && vLocalPos.y < 2.38 && abs(vLocalPos.x) < 0.092) discard;',\n          '  vec3 N = normalize(vNormal);',\n          '  vec3 V = normalize(vViewDir);',\n          '  vec3 L = normalize(vec3(0.38, 0.72, 0.68));',\n          '  float nl = dot(N, L) * 0.5 + 0.5;',\n          '  float nv = clamp(abs(dot(N, V)), 0.0, 1.0);',\n          '  vec3 col = mix(uShadow, uMid, smoothstep(0.35, 0.44, nl));',\n          '  col = mix(col, uHigh, smoothstep(0.65, 0.74, nl));',\n          '  if (uMotionMode > 3.5) {',\n          '    float distFromHeart = length(vOrigWorldPos - vec3(0.03, 3.53, 0.02));',\n          '    float wave = pow(0.5 + 0.5 * sin(distFromHeart * 8.5 + uFlowDir * uTime * 5.2), 4.0);',\n          '    vec3 pulseTint = uFlowDir < 0.0 ? vec3(1.0, 0.82, 0.62) : vec3(0.70, 0.90, 1.0);',\n          '    col = mix(col, pulseTint, wave * 0.42);',\n          '  }',\n          '  col = mix(col, uOutline, smoothstep(0.74, 0.86, 1.0 - nv) * 0.65);',\n          '  col = applyRegionFocusGlow(col, vOrigWorldPos);',\n          '  gl_FragColor = vec4(col, uOpacity);',\n          '}'\n        ].join('\\n'),\n        transparent: true,\n        depthWrite: true\n      });\n    }\n\n    let vascularGroup = null;\n    const vascularArtMat = createVascularMaterial('#EB665E', '#C73B35', '#8C1F1B', '#4D0E0B', 0.92, -1.0);\n    const vascularVenMat = createVascularMaterial('#6EA7F0', '#3E76C2', '#224C87', '#112A4D', 0.89,  1.0);\n    gltfLoader.load('models/Vascular.glb', (gltf) => {\n      vascularGroup = gltf.scene;\n      vascularGroup.visible = false;\n      vascularGroup.traverse(c => {\n        if (c.isMesh) {\n          c.material = (c.name || '').includes('Venous') ? vascularVenMat : vascularArtMat;\n          c.renderOrder = 5;\n        }\n      });\n      scene.add(vascularGroup);\n      updateAnatomyHighlight();\n    });\n\n    // 2.8 Full Head-to-Toe Central & Peripheral Nervous System (Brainstem -> Spinal Cord -> Cranial/Brachial/Intercostal/Sciatic -> Fingers & Toes)\n    function createNeuralImpulseMaterial() {\n      return new THREE.ShaderMaterial({\n        uniforms: Object.assign({\n          uBaseGold: { value: new THREE.Color('#E8BD56') },\n          uDeepGold: { value: new THREE.Color('#9E7318') },\n          uSparkCol: { value: new THREE.Color('#FFFBE6') }\n        }, sharedMotionUniforms),\n        vertexShader: [\n          GLSL_MOTION_CHUNK,\n          'varying vec2 vUv;',\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vUv = uv;',\n          '  vec4 origWorld = modelMatrix * vec4(position, 1.0);',\n          '  vOrigWorldPos = origWorld.xyz;',\n          '  vec4 worldPos = vec4(applySystemBodyMotion(origWorld.xyz), 1.0);',\n          '  vec4 mvPos = viewMatrix * worldPos;',\n          '  vViewDir = normalize(-mvPos.xyz);',\n          '  vNormal = normalize(normalMatrix * normal);',\n          '  gl_Position = projectionMatrix * mvPos;',\n          '}'\n        ].join('\\n'),\n        fragmentShader: [\n          GLSL_MOTION_CHUNK,\n          'uniform vec3 uBaseGold;',\n          'uniform vec3 uDeepGold;',\n          'uniform vec3 uSparkCol;',\n          'varying vec2 vUv;',\n          'varying vec3 vNormal;',\n          'varying vec3 vViewDir;',\n          'varying vec3 vOrigWorldPos;',\n          'void main() {',\n          '  vec3 N = normalize(vNormal);',\n          '  vec3 V = normalize(vViewDir);',\n          '  vec3 L = normalize(vec3(0.40, 0.76, 0.66));',\n          '  float nl = dot(N, L) * 0.5 + 0.5;',\n          '  vec3 col = mix(uDeepGold, uBaseGold, smoothstep(0.30, 0.68, nl));',\n          '  float travel = fract(vUv.x * 2.2 - uTime * 0.85);',\n          '  float spark = exp(-pow((travel - 0.5) * 7.5, 2.0));',\n          '  col = mix(col, uSparkCol, spark * 0.80);',\n          '  col = applyRegionFocusGlow(col, vOrigWorldPos);',\n          '  gl_FragColor = vec4(col, 0.98);',\n          '}'\n        ].join('\\n'),\n        transparent: true,\n        depthWrite: true\n      });\n    }\n\n    function createFullBodyNerveSystem3DGroup() {\n      const group = new THREE.Group();\n      const impulseMat = createNeuralImpulseMaterial();\n      const ganglionMat = createToonClayMaterial('#FFF6B8', '#E8BD52', '#A87A14', '#593E04', 0.99, 0.25, 2.0);\n\n      function addNerveTube(pts, radius, segs) {\n        const curve = new THREE.CatmullRomCurve3(pts.map(p => new THREE.Vector3(p[0], p[1], p[2])));\n        const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, segs || 40, radius, 10, false), impulseMat);\n        mesh.renderOrder = 8;\n        group.add(mesh);\n      }\n\n      // Central Spinal Cord (Brainstem Medulla y=4.16 -> Cervical -> Thoracic -> Lumbar Conus -> Sacral Filum y=2.30)\n      addNerveTube([\n        [0.0, 4.18, -0.04],\n        [0.0, 3.85, -0.07],\n        [0.0, 3.45, -0.10],\n        [0.0, 3.05, -0.08],\n        [0.0, 2.72, -0.06],\n        [0.0, 2.34, -0.07]\n      ], 0.013, 64);\n\n      // Spinal Dorsal Root Ganglia Nodes along C2..S2\n      [4.02, 3.88, 3.74, 3.58, 3.42, 3.26, 3.10, 2.94, 2.78, 2.62, 2.46].forEach(y => {\n        [-1, 1].forEach(dir => {\n          const g = new THREE.Mesh(new THREE.SphereGeometry(0.011, 12, 12), ganglionMat);\n          g.position.set(dir * 0.024, y, -0.075);\n          g.renderOrder = 8;\n          group.add(g);\n        });\n      });\n\n      // Bilateral Cranial, Brachial (to 5 fingers), Intercostal, Vagus, Femoral & Sciatic-Tibial-Peroneal (to toes)\n      [-1, 1].forEach(dir => {\n        // 1. Cranial Nerves (Trigeminal V & Facial VII to face/TMJ + Greater Occipital)\n        addNerveTube([\n          [dir * 0.02, 4.20, -0.02],\n          [dir * 0.08, 4.17,  0.02],\n          [dir * 0.09, 4.11,  0.11],\n          [dir * 0.05, 4.05,  0.16]\n        ], 0.0052, 24);\n        addNerveTube([\n          [dir * 0.02, 4.04, -0.07],\n          [dir * 0.06, 4.20, -0.15],\n          [dir * 0.05, 4.38, -0.11]\n        ], 0.0048, 20);\n\n        // 2. Vagus & Autonomic Trunk (Neck -> Heart -> Solar Plexus)\n        addNerveTube([\n          [dir * 0.025, 4.10, -0.03],\n          [dir * 0.042, 3.82,  0.00],\n          [dir * 0.045, 3.52,  0.03],\n          [dir * 0.028, 3.12,  0.03],\n          [dir * 0.032, 2.78,  0.01]\n        ], 0.0058, 36);\n\n        // 3. Brachial Plexus -> Median Nerve (down arm, carpal tunnel, thumb/index/middle fingers)\n        addNerveTube([\n          [dir * 0.028, 3.78, -0.07],\n          [dir * 0.220, 3.68, -0.08],\n          [dir * 0.445, 3.52, -0.11],\n          [dir * 0.555, 3.06, -0.12],\n          [dir * 0.592, 2.86, -0.09],\n          [dir * 0.645, 2.58, -0.02],\n          [dir * 0.706, 2.33,  0.064],\n          [dir * 0.720, 2.10,  0.145]\n        ], 0.0072, 56);\n\n        // Ulnar & Radial Nerve Companion Tracts + Digital Branches to Fingers\n        addNerveTube([\n          [dir * 0.455, 3.50, -0.12],\n          [dir * 0.575, 3.04, -0.14],\n          [dir * 0.610, 2.85, -0.11],\n          [dir * 0.668, 2.56, -0.04],\n          [dir * 0.735, 2.32,  0.045],\n          [dir * 0.758, 2.09,  0.115]\n        ], 0.0054, 44);\n        addNerveTube([\n          [dir * 0.706, 2.33,  0.064],\n          [dir * 0.675, 2.16,  0.165]\n        ], 0.0044, 16);\n\n        // 4. Thoracic Intercostal Nerves (3 representative rib-hugging arcs)\n        [3.48, 3.28, 3.08].forEach((ry, idx) => {\n          const w = 0.24 - idx * 0.015;\n          addNerveTube([\n            [dir * 0.025, ry, -0.09],\n            [dir * (w * 0.72), ry - 0.03, -0.06],\n            [dir * w, ry - 0.06, 0.04],\n            [dir * (w * 0.55), ry - 0.08, 0.11]\n          ], 0.0044, 24);\n        });\n\n        // 5. Femoral & Saphenous Nerve (Lumbar Plexus -> Anterior Thigh -> Medial Knee/Shin)\n        addNerveTube([\n          [dir * 0.030, 2.76, -0.06],\n          [dir * 0.165, 2.46, -0.03],\n          [dir * 0.255, 2.26, -0.03],\n          [dir * 0.305, 1.82, -0.06],\n          [dir * 0.335, 1.24, -0.11],\n          [dir * 0.380, 0.78, -0.15],\n          [dir * 0.420, 0.22, -0.07]\n        ], 0.0064, 48);\n\n        // 6. Sciatic Nerve -> Tibial Nerve -> Tarsal Tunnel -> Plantar & Toe Digital Nerves\n        addNerveTube([\n          [dir * 0.035, 2.52, -0.07],\n          [dir * 0.145, 2.38, -0.10],\n          [dir * 0.255, 2.22, -0.11],\n          [dir * 0.325, 1.78, -0.12],\n          [dir * 0.362, 1.22, -0.16],\n          [dir * 0.412, 0.80, -0.21],\n          [dir * 0.446, 0.18, -0.10],\n          [dir * 0.485, 0.06,  0.08],\n          [dir * 0.505, 0.045, 0.25]\n        ], 0.0085, 64);\n\n        // Common Peroneal (Fibular) Nerve -> Dorsum of Foot & Lateral Toes\n        addNerveTube([\n          [dir * 0.362, 1.24, -0.16],\n          [dir * 0.435, 0.86, -0.17],\n          [dir * 0.462, 0.20, -0.05],\n          [dir * 0.495, 0.08,  0.12],\n          [dir * 0.535, 0.05,  0.24]\n        ], 0.0056, 36);\n      });\n\n      group.visible = false;\n      scene.add(group);\n      return group;\n    }\n    const fullBodyNerveGroup = createFullBodyNerveSystem3DGroup();\n\n    // Autonomic Nerve Subset for Clinic Vasovagal Syncope View\n    function createAutonomicNerve3DGroup() {\n      const group = new THREE.Group();\n      const nerveMat = createToonClayMaterial('#FFF099', '#F2C94C', '#C49416', '#6E4F04', 0.98, 0.20);\n      [\n        [0.0, 4.10, -0.02, 0.024],\n        [0.03, 3.52, 0.04, 0.020],\n        [0.0, 3.12, 0.03, 0.022],\n        [0.0, 2.48, 0.02, 0.018]\n      ].forEach(([x, y, z, r]) => {\n        const node = new THREE.Mesh(new THREE.SphereGeometry(r, 20, 20), nerveMat);\n        node.position.set(x, y, z);\n        node.renderOrder = 8;\n        group.add(node);\n      });\n\n      [-1, 1].forEach(dir => {\n        const vagusPath = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.022, 4.12, -0.02),\n          new THREE.Vector3(dir * 0.038, 3.85,  0.00),\n          new THREE.Vector3(dir * 0.042, 3.52,  0.03),\n          new THREE.Vector3(dir * 0.028, 3.12,  0.03),\n          new THREE.Vector3(dir * 0.035, 2.75,  0.01),\n          new THREE.Vector3(dir * 0.045, 2.45,  0.00),\n          new THREE.Vector3(dir * 0.115, 1.85, -0.04),\n          new THREE.Vector3(dir * 0.145, 1.20, -0.08),\n          new THREE.Vector3(dir * 0.155, 0.55, -0.08)\n        ]);\n        const vagusMesh = new THREE.Mesh(new THREE.TubeGeometry(vagusPath, 64, 0.0075, 12, false), nerveMat);\n        vagusMesh.renderOrder = 8;\n        group.add(vagusMesh);\n\n        const armPath = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.040, 3.78,  0.00),\n          new THREE.Vector3(dir * 0.180, 3.62, -0.02),\n          new THREE.Vector3(dir * 0.310, 3.15, -0.03),\n          new THREE.Vector3(dir * 0.420, 2.55,  0.02)\n        ]);\n        const armMesh = new THREE.Mesh(new THREE.TubeGeometry(armPath, 32, 0.0055, 10, false), nerveMat);\n        armMesh.renderOrder = 8;\n        group.add(armMesh);\n      });\n\n      group.visible = false;\n      scene.add(group);\n      return group;\n    }\n    const autonomicNerveGroup = createAutonomicNerve3DGroup();\n\n    // Heart-Brain Golden Vitality Stream for Emperor Gongjindan\n    function createGongjindanBridgeGroup() {\n      const group = new THREE.Group();\n      const goldMat = createToonClayMaterial('#FFF2A6', '#E5B842', '#AD8018', '#5E4306', 0.95, 0.20);\n      [-1, 1].forEach(dir => {\n        const curve = new THREE.CatmullRomCurve3([\n          new THREE.Vector3(dir * 0.025, 3.52, 0.04),\n          new THREE.Vector3(dir * 0.048, 3.88, 0.02),\n          new THREE.Vector3(dir * 0.032, 4.26, 0.00)\n        ]);\n        const m = new THREE.Mesh(new THREE.TubeGeometry(curve, 32, 0.007, 12, false), goldMat);\n        m.renderOrder = 7;\n        group.add(m);\n      });\n      group.visible = false;\n      scene.add(group);\n      return group;\n    }\n    const gongjindanBridgeGroup = createGongjindanBridgeGroup();\n\n    // ========================================================================\n    // 3. 9 CLINIC HOTSPOTS + 12 HEAD-TO-TOE ANATOMY SYSTEM HOTSPOTS\n    // ========================================================================\n    const LEFT_ALIGNED_PARTS = ['cervical', 'gut', 'uterus'];\n    const HOTSPOT_3D_ANCHORS = {\n      syncope:    [ 0.08, 4.34,  0.04],\n      cervical:   [-0.08, 3.92,  0.04],\n      gongjindan: [ 0.08, 3.52,  0.08],\n      digest:     [ 0.08, 3.22,  0.08],\n      gut:        [-0.08, 3.06,  0.08],\n      lumbar:     [ 0.08, 2.76,  0.04],\n      uterus:     [-0.10, 2.44,  0.05],\n      prostate:   [ 0.10, 2.24,  0.05],\n      knee:       [ 0.16, 1.20,  0.05]\n    };\n\n    const majorHotspotNodes = [];\n    BODY_PARTS_DATA.forEach((part) => {\n      const anchor = HOTSPOT_3D_ANCHORS[part.id] || [0, 3.0, 0];\n      const isLeft = LEFT_ALIGNED_PARTS.includes(part.id);\n      const dom = document.createElement('div');\n      dom.className = 'body-3d-hotspot' + (isLeft ? ' align-left' : '');\n      dom.innerHTML =\n        '<div class=\"hotspot-pulse-ring\">' +\n          '<div class=\"hotspot-core-dot\"></div>' +\n          '<div class=\"hotspot-core-dot\"></div>' +\n          '<div class=\"hotspot-core-dot\"></div>' +\n        '</div>' +\n        '<div class=\"hotspot-tag-pill\">' + part.hotspotLabel + '</div>';\n      dom.addEventListener('click', () => window.selectBodyPart(part.id, true));\n      hotspotLayer.appendChild(dom);\n      majorHotspotNodes.push({\n        id: part.id,\n        part: part,\n        dom: dom,\n        basePos: anchor.slice(),\n        worldPos: new THREE.Vector3(...anchor)\n      });\n    });\n\n    const systemHotspotNodes = [];\n    if (typeof ANATOMY_REGIONS !== 'undefined' && Array.isArray(ANATOMY_REGIONS)) {\n      ANATOMY_REGIONS.forEach((reg) => {\n        const dom = document.createElement('div');\n        dom.className = 'body-3d-hotspot system-region-hotspot';\n        dom.style.display = 'none';\n        dom.title = reg.num + '. ' + reg.regionLabel;\n        dom.innerHTML =\n          '<div class=\"hotspot-pulse-ring sys-ring\">' +\n            '<span class=\"sys-hotspot-num\">' + reg.num + '</span>' +\n          '</div>' +\n          '<div class=\"sys-hotspot-label\">' + reg.shortLabel + '</div>';\n        dom.addEventListener('click', () => {\n          if (typeof window.selectSystemRegion === 'function') {\n            window.selectSystemRegion(reg.id, true);\n          }\n        });\n        hotspotLayer.appendChild(dom);\n        systemHotspotNodes.push({\n          id: reg.id,\n          reg: reg,\n          dom: dom,\n          basePos: reg.pos3D.slice(),\n          worldPos: new THREE.Vector3(...reg.pos3D)\n        });\n      });\n    }\n\n    // ========================================================================\n    // 4. CAMERA FLY-TO, RESET VIEW & UNIFIED ANATOMY / 4-SYSTEM HIGHLIGHT\n    // ========================================================================\n    const DEFAULT_CAM_POS = new THREE.Vector3(0.0, 2.28, 5.65);\n    const DEFAULT_CAM_TARGET = new THREE.Vector3(0.0, 2.26, 0.0);\n    const camGoalPos = DEFAULT_CAM_POS.clone();\n    const camGoalTarget = DEFAULT_CAM_TARGET.clone();\n    let isCameraFlying = false;\n    let isOverviewCamera = true;\n\n    controls.addEventListener('start', () => {\n      isCameraFlying = false;\n    });\n\n    function updateAnatomyHighlight() {\n      const sysMode = (typeof currentSystemMode !== 'undefined') ? currentSystemMode : null;\n      const sysRegId = (typeof currentSystemRegionId !== 'undefined') ? currentSystemRegionId : 'all';\n      const isClinicActive = Boolean(!sysMode && typeof isPopupOpen !== 'undefined' && isPopupOpen);\n      const isAnyActive = Boolean(sysMode || isClinicActive);\n\n      // Update motion mode & amplitude (calm amplitude slightly when zoomed tightly into a single region)\n      const modeMap = { muscle: 1.0, nerve: 2.0, joint: 3.0, vessel: 4.0 };\n      sharedMotionUniforms.uMotionMode.value = sysMode ? (modeMap[sysMode] || 0.0) : 0.0;\n      sharedMotionUniforms.uMotionAmp.value = (sysMode && sysRegId && sysRegId !== 'all') ? 0.42 : 1.0;\n\n      // Update 3D Champagne-Gold region focus sphere\n      if (sysMode && sysRegId && sysRegId !== 'all' && typeof ANATOMY_REGIONS !== 'undefined') {\n        const regMeta = ANATOMY_REGIONS.find(r => r.id === sysRegId);\n        if (regMeta) {\n          sharedMotionUniforms.uFocusActive.value = 1.0;\n          sharedMotionUniforms.uFocusCenter.value.set(...regMeta.focusCenter);\n          sharedMotionUniforms.uFocusRadius.value = regMeta.focusRadius || 0.36;\n        } else {\n          sharedMotionUniforms.uFocusActive.value = 0.0;\n        }\n      } else {\n        sharedMotionUniforms.uFocusActive.value = 0.0;\n      }\n\n      // Toggle hotspot sets (Clinic 9 vs System 12)\n      majorHotspotNodes.forEach(h => {\n        h.dom.style.display = sysMode ? 'none' : 'flex';\n      });\n      systemHotspotNodes.forEach(sh => {\n        sh.dom.style.display = sysMode ? 'flex' : 'none';\n        sh.dom.classList.toggle('active', Boolean(sysMode && sh.id === sysRegId));\n      });\n\n      // Skin material mode: Porcelain opaque (idle) / Muscle Écorché (muscle) / Translucent X-Ray (nerve, joint, vessel, clinic)\n      const isMuscle = (sysMode === 'muscle');\n      [maleSkinMat, femaleSkinMat].forEach(mat => {\n        if (!mat || !mat.uniforms) return;\n        mat.uniforms.uMuscleMode.value = isMuscle ? 1.0 : 0.0;\n        if (!isAnyActive) {\n          mat.uniforms.uCenterAlpha.value = 0.88;\n          mat.depthWrite = true;\n        } else if (isMuscle) {\n          mat.uniforms.uCenterAlpha.value = 0.96;\n          mat.depthWrite = true;\n        } else {\n          mat.uniforms.uCenterAlpha.value = sysMode ? 0.16 : 0.22;\n          mat.depthWrite = false;\n        }\n      });\n\n      // Reset everything first when completely idle\n      if (!isAnyActive) {\n        uterus3D.group.visible = false;\n        prostate3D.group.visible = false;\n        if (vascularGroup) vascularGroup.visible = false;\n        autonomicNerveGroup.visible = false;\n        fullBodyNerveGroup.visible = false;\n        gongjindanBridgeGroup.visible = false;\n        if (jointsGlbGroup) jointsGlbGroup.visible = false;\n        if (spinalDiscs3D && spinalDiscs3D.group) spinalDiscs3D.group.visible = false;\n        Object.keys(boneIllustrationMap).forEach(gName => {\n          boneIllustrationMap[gName].mesh.visible = false;\n        });\n        Object.keys(loadedOrgans).forEach(key => {\n          loadedOrgans[key].scene.visible = false;\n        });\n        return;\n      }\n\n      // 4-SYSTEM BOTTOM MENU MODES ('muscle' | 'nerve' | 'joint' | 'vessel')\n      if (sysMode) {\n        uterus3D.group.visible = false;\n        prostate3D.group.visible = false;\n        autonomicNerveGroup.visible = false;\n        gongjindanBridgeGroup.visible = false;\n        if (spinalDiscs3D && spinalDiscs3D.group) spinalDiscs3D.group.visible = false;\n\n        // Nerves\n        fullBodyNerveGroup.visible = (sysMode === 'nerve');\n\n        // Vessels\n        if (vascularGroup) {\n          vascularGroup.visible = (sysMode === 'vessel');\n          vascularArtMat.uniforms.uClipPelvis.value = 1.0;\n          vascularVenMat.uniforms.uClipPelvis.value = 1.0;\n        }\n\n        // Joints & Full Head-to-Toe Skeleton\n        if (jointsGlbGroup) {\n          jointsGlbGroup.visible = (sysMode === 'joint');\n        }\n        Object.keys(boneIllustrationMap).forEach(gName => {\n          const entry = boneIllustrationMap[gName];\n          if (sysMode === 'joint') {\n            entry.mesh.visible = true;\n            entry.mat.uniforms.uOpacity.value = gName.includes('KneeGrowthPlate') ? 0.98 : 0.92;\n            entry.mat.depthWrite = true;\n          } else {\n            entry.mesh.visible = false;\n          }\n        });\n\n        // Organs in System Mode: Brain for 'nerve', Beating Heart for 'vessel'\n        Object.keys(loadedOrgans).forEach(key => {\n          const entry = loadedOrgans[key];\n          const showOrgan = (sysMode === 'nerve' && key === 'brain') || (sysMode === 'vessel' && key === 'heart');\n          entry.scene.visible = showOrgan;\n          entry.mat.uniforms.uOpacity.value = showOrgan ? 0.97 : 0.0;\n          entry.mat.depthWrite = showOrgan;\n        });\n        return;\n      }\n\n      // RIGHT-SIDE CLINIC EXPLORE MENU MODE (Preserved 100%)\n      fullBodyNerveGroup.visible = false;\n      if (jointsGlbGroup) jointsGlbGroup.visible = false;\n      uterus3D.group.visible = (currentPartId === 'uterus');\n      prostate3D.group.visible = (currentPartId === 'prostate');\n      if (vascularGroup) {\n        vascularGroup.visible = (currentPartId === 'syncope');\n        vascularArtMat.uniforms.uClipPelvis.value = 1.0;\n        vascularVenMat.uniforms.uClipPelvis.value = 1.0;\n      }\n      autonomicNerveGroup.visible = (currentPartId === 'syncope');\n      gongjindanBridgeGroup.visible = (currentPartId === 'gongjindan');\n\n      const boneHighlightMap = {\n        knee:       ['KneeJointBones', 'KneeGrowthPlate', 'LowerLimbs'],\n        cervical:   ['CervicalSpine'],\n        lumbar:     ['LumbarSpine', 'Pelvis'],\n        gongjindan: ['CervicalSpine'],\n        syncope:    [],\n        digest:     [],\n        gut:        [],\n        uterus:     ['Pelvis', 'LumbarSpine'],\n        prostate:   ['Pelvis', 'LumbarSpine']\n      };\n      const activeBones = boneHighlightMap[currentPartId] || [];\n\n      Object.keys(boneIllustrationMap).forEach(gName => {\n        const entry = boneIllustrationMap[gName];\n        const isMatched = activeBones.some(b => gName.includes(b));\n        entry.mesh.visible = isMatched;\n        if (isMatched) {\n          const isGP = gName.includes('KneeGrowthPlate');\n          const isSupport = (currentPartId === 'uterus' || currentPartId === 'prostate' || currentPartId === 'gongjindan');\n          entry.mat.uniforms.uOpacity.value = isGP ? 0.98 : (isSupport ? 0.42 : 0.94);\n          entry.mat.depthWrite = !isSupport;\n        }\n      });\n\n      if (spinalDiscs3D && spinalDiscs3D.group) {\n        const showDiscs = ['lumbar', 'cervical', 'uterus', 'prostate'].includes(currentPartId);\n        spinalDiscs3D.group.visible = showDiscs;\n        if (showDiscs) {\n          const discAlpha = (currentPartId === 'lumbar' || currentPartId === 'cervical') ? 0.98 : 0.55;\n          spinalDiscs3D.mats.forEach(m => { m.uniforms.uOpacity.value = discAlpha; });\n        }\n      }\n\n      Object.keys(loadedOrgans).forEach(key => {\n        const entry = loadedOrgans[key];\n        const isTarget = (currentPartId === 'syncope')\n          ? (key === 'brain' || key === 'heart')\n          : entry.cfg.parts.includes(currentPartId);\n        entry.scene.visible = isTarget;\n        entry.mat.uniforms.uOpacity.value = isTarget ? 0.97 : 0.0;\n        entry.mat.depthWrite = isTarget;\n      });\n    }",
  "partB": "    window.setDonginGender = function(gender) {\n      currentGender = gender;\n      document.getElementById('btn-gender-male')?.classList.toggle('active', gender === 'male');\n      document.getElementById('btn-gender-female')?.classList.toggle('active', gender === 'female');\n      if (maleBodyObj) maleBodyObj.visible = (gender === 'male');\n      if (femaleBodyObj) femaleBodyObj.visible = (gender === 'female');\n    };\n\n    window.flyDonginCameraTo = function(posArr, targetArr, isOverview) {\n      isOverviewCamera = Boolean(isOverview);\n      camGoalPos.set(posArr[0], posArr[1], posArr[2]);\n      camGoalTarget.set(targetArr[0], targetArr[1], targetArr[2]);\n      isCameraFlying = true;\n    };\n\n    window.syncDonginAnatomy = function() {\n      updateAnatomyHighlight();\n    };\n\n    window.resetDonginView = function() {\n      isOverviewCamera = true;\n      isCameraFlying = true;\n      camGoalPos.copy(DEFAULT_CAM_POS);\n      camGoalTarget.copy(DEFAULT_CAM_TARGET);\n      updateAnatomyHighlight();\n    };\n\n    quickNavButtons.forEach(btn => {\n      btn.addEventListener('click', () => {\n        window.selectBodyPart(btn.getAttribute('data-part'), true);\n      });\n    });\n\n    function resizeRenderer() {\n      if (!stageEl) return;\n      const w = Math.max(320, stageEl.clientWidth || Math.round(window.innerWidth * 0.44));\n      const h = Math.max(320, stageEl.clientHeight || (window.innerHeight - 62));\n      renderer.setSize(w, h, false);\n      const aspect = w / Math.max(1, h);\n      camera.aspect = aspect;\n      const focal = aspect < 0.72 ? Math.max(22, 38 * (aspect / 0.72)) : 38;\n      camera.setFocalLength(focal);\n      camera.updateProjectionMatrix();\n    }\n    window.addEventListener('resize', resizeRenderer);\n    if (window.ResizeObserver && stageEl) {\n      new ResizeObserver(() => resizeRenderer()).observe(stageEl);\n    }\n    resizeRenderer();\n\n    // ========================================================================\n    // 5. 60FPS RENDER LOOP (REAL-TIME SYSTEM MOTION CLOCK & HOTSPOT PROJECTION)\n    // ========================================================================\n    const projVec = new THREE.Vector3();\n    const clockStart = performance.now();\n\n    function projectHotspotNode(item, w, h, useMotionOffset) {\n      if (item.dom.style.display === 'none') return;\n      if (useMotionOffset && item.basePos) {\n        const moved = evalSystemBodyMotionJS(item.basePos[0], item.basePos[1], item.basePos[2]);\n        item.worldPos.set(moved[0], moved[1], moved[2]);\n      }\n      projVec.copy(item.worldPos).project(camera);\n      if (projVec.z > 1.0) {\n        item.dom.style.opacity = '0';\n        return;\n      }\n      const sx = (projVec.x * 0.5 + 0.5) * w;\n      const sy = (-projVec.y * 0.5 + 0.5) * h;\n      item.dom.style.left = sx.toFixed(1) + 'px';\n      item.dom.style.top = sy.toFixed(1) + 'px';\n      const inBounds = (sx > 18 && sx < w - 18 && sy > 36 && sy < h - 46);\n      item.dom.style.opacity = inBounds ? '1' : '0';\n    }\n\n    function animate() {\n      requestAnimationFrame(animate);\n      sharedMotionUniforms.uTime.value = (performance.now() - clockStart) * 0.001;\n\n      if (isCameraFlying) {\n        camera.position.lerp(camGoalPos, 0.085);\n        controls.target.lerp(camGoalTarget, 0.095);\n        if (camera.position.distanceTo(camGoalPos) < 0.012) {\n          isCameraFlying = false;\n        }\n      }\n      controls.update();\n\n      const w = stageEl.clientWidth;\n      const h = stageEl.clientHeight;\n      const sysActive = Boolean(typeof currentSystemMode !== 'undefined' && currentSystemMode);\n\n      if (sysActive) {\n        systemHotspotNodes.forEach(item => projectHotspotNode(item, w, h, true));\n      } else {\n        majorHotspotNodes.forEach(item => projectHotspotNode(item, w, h, false));\n      }\n\n      renderer.render(scene, camera);\n    }"
};
